/**
 * Where a Session's notes live, and how many there are.
 *
 * This is the route's only trust boundary: the notes directory is derived from
 * the session, never from a path the browser supplies.
 *
 * A live session carries its header in memory; a session restored after a
 * restart does not, and only persistence knows it.
 */
import { MAX_COUNT_IDS, describe } from './protocol.js'
import { countNotes, isStoreName } from './notes.js'

/**
 * Session id → workspace root, once resolved.
 *
 * A session's working directory is fixed when the session is created, so a
 * successful resolution never goes stale; only successes are cached, because a
 * session persistence that is not ready yet may answer later.
 * @type {Map<string, string>}
 */
const resolved = new Map()

/** What an unaddressable session id is refused with. */
const BAD_ID = {
  code: 'unknown-session',
  message: 'That session id cannot name a notes directory.',
}

/**
 * Resolve one session's workspace directory.
 * @param {import('@deepseek-ai/cordis').Context} ctx - host context.
 * @param {unknown} sessionId - session identity from the request.
 * @returns {Promise<{ root?: string, code?: string, message?: string }>}
 *   `{ root }`, or `{ code, message }` to answer with.
 */
export async function sessionRootOf(ctx, sessionId) {
  if (typeof sessionId !== 'string' || sessionId.length === 0) {
    return { code: 'bad-request', message: 'sessionId is required.' }
  }
  if (!isStoreName(sessionId)) return BAD_ID

  const known = resolved.get(sessionId)
  if (known !== undefined) return { root: known }

  const live = ctx.sessions.get(sessionId)
  const fromLive = live?.header?.cwd
  if (typeof fromLive === 'string' && fromLive.length > 0) {
    resolved.set(sessionId, fromLive)
    return { root: fromLive }
  }

  const persistence = ctx.get('sessionPersistence')
  if (persistence !== undefined) {
    try {
      // `sessionPersistence.stat` answers `{ header, revision }`; `header` is
      // the immutable Session header. Reading any other field here resolves
      // nothing for a Session that is not open, so every unopened row would
      // report no notes until its conversation is opened once.
      const stored = await persistence.stat(sessionId)
      const fromStore = stored?.header?.cwd
      if (typeof fromStore === 'string' && fromStore.length > 0) {
        resolved.set(sessionId, fromStore)
        return { root: fromStore }
      }
    } catch (error) {
      return {
        code: 'unknown-session',
        message: `That session's workspace is unavailable: ${describe(error)}`,
      }
    }
  }

  return {
    code: 'unknown-session',
    message: 'That session has no known workspace directory, so its notes cannot be found.',
  }
}

/**
 * How many notes one Session holds.
 * @param {import('@deepseek-ai/cordis').Context} ctx - host context.
 * @param {string} sessionId - session identity.
 * @returns {Promise<number | undefined>} the count, or undefined when this
 *   session's directory cannot be resolved.
 */
async function countOf(ctx, sessionId) {
  const resolution = await sessionRootOf(ctx, sessionId)
  if (resolution.root === undefined) return undefined
  try {
    return await countNotes(resolution.root, sessionId)
  } catch {
    // One unreadable directory must not cost the other rows their counts.
    return undefined
  }
}

/**
 * Note counts for one batch of Sessions.
 * @param {import('@deepseek-ai/cordis').Context} ctx - host context.
 * @param {unknown} sessionIds - the requested Session ids.
 * @returns {Promise<{ value?: Record<string, number>, code?: string, message?: string }>}
 *   `{ value }` keyed by the ids that resolved, or `{ code, message }`.
 */
export async function countsBySession(ctx, sessionIds) {
  if (!Array.isArray(sessionIds)) {
    return { code: 'bad-request', message: 'sessionIds must be an array.' }
  }
  if (sessionIds.length > MAX_COUNT_IDS) {
    return { code: 'bad-request', message: `sessionIds is limited to ${MAX_COUNT_IDS} entries.` }
  }

  const counts = {}
  for (const id of sessionIds) {
    if (!isStoreName(id)) continue
    const count = await countOf(ctx, id)
    // An id this Host cannot resolve is simply absent from the answer; its row
    // keeps no badge rather than showing a number nobody verified.
    if (count !== undefined) counts[id] = count
  }
  return { value: counts }
}

/**
 * Note counts for one batch of registered Workspaces.
 *
 * The request names Workspaces, not paths: every id is resolved through the
 * Host's own registry, so this answer can only ever describe directories the
 * Host already knows about. A Workspace's count is the sum of its Sessions'
 * counts — the same fact as the Session rows show, added up, not a second
 * reading of the disk.
 * @param {import('@deepseek-ai/cordis').Context} ctx - host context.
 * @param {unknown} workspaceIds - the requested Workspace ids.
 * @returns {Promise<{ value?: Record<string, number>, code?: string, message?: string }>}
 *   `{ value }` keyed by the ids that resolved, or `{ code, message }`.
 */
export async function countsByWorkspace(ctx, workspaceIds) {
  if (!Array.isArray(workspaceIds)) {
    return { code: 'bad-request', message: 'workspaceIds must be an array.' }
  }
  if (workspaceIds.length > MAX_COUNT_IDS) {
    return { code: 'bad-request', message: `workspaceIds is limited to ${MAX_COUNT_IDS} entries.` }
  }

  const registry = ctx.get('workspaceRegistry')
  if (registry === undefined) {
    return { code: 'io-error', message: 'The workspace registry is not available.' }
  }

  const counts = {}
  for (const id of workspaceIds) {
    if (typeof id !== 'string' || id.length === 0) continue
    const workspace = registry.get(id)
    if (workspace === undefined) continue
    let total = 0
    for (const sessionId of workspace.sessionIds) {
      total += (await countOf(ctx, sessionId)) ?? 0
    }
    counts[id] = total
  }
  return { value: counts }
}
